use serde::{Deserialize, Serialize};

use crate::models::{OpenAiResponseInputTokensDetails, OpenAiResponseOutputTokensDetails};

/// OpenAI-compatible open ai response usage schema exposed by Claw Router.
#[derive(Serialize, Deserialize, Debug, Clone, Default)]
pub struct OpenAiResponseUsage {
    /// Number of input tokens billed for the response.
    pub input_tokens: i64,

    /// Input tokens details field on the open ai response usage, using the open ai response input tokens details module.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub input_tokens_details: Option<OpenAiResponseInputTokensDetails>,

    /// Number of output tokens generated by the response.
    pub output_tokens: i64,

    /// Output tokens details field on the open ai response usage, using the open ai response output tokens details module.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub output_tokens_details: Option<OpenAiResponseOutputTokensDetails>,

    /// Total input and output token count.
    pub total_tokens: i64,
}
